function pascal(rows) {
  var triangle = [];
  for (var n = 0; n < rows; n++) {
    var row = [1];
    for (var k = 1; k < n; k++) {
      row.push(triangle[n - 1][k - 1] + triangle[n - 1][k]);
    }
    if (n > 0) {
      row.push(1);
    }
    triangle.push(row);
  }
  return triangle;
}

